#[path="../setup/fast.rs"]mod fast;
#[path="../multi/algebra.rs"]mod algebra;
#[path="../normalized/source.rs"]mod source;
#[path="../orbit-core/sparse.rs"]mod sparse;
#[allow(dead_code)]#[path="../affine-promotion/dsu.rs"]mod dsu;
use hec_native_ic::{counted,fp::Fp,jac::{Curve,Div},poly::Poly,rng::Rng,oracle::{split_reference,OracleStats},solve::{solve_for_last,Row,SolveStats,Solver}};
use std::{collections::BTreeMap,fs};
fn sparse(v:&[u64])->Row{v.iter().enumerate().filter_map(|(j,&x)|(x!=0).then_some((j as u32,x))).collect()}
fn insert(c:&Curve,d:&Div,t:&Div,ell:u64,v:Vec<u64>,rhs:u64,rows:&mut Vec<(Row,u64)>,a:&mut dsu::Affine,b:&mut sparse::Sparse){a.insert(&v,rhs);b.insert(&v,rhs);rows.push((sparse(&v),rhs));let mut stats=SolveStats::default();let k=solve_for_last(rows,v.len()-1,ell,Solver::Fast,&[],&mut stats);assert_eq!(k,a.k());assert_eq!(k,b.k());assert_eq!(a.rank(),b.rank);if let Some(k)=k{assert_eq!(c.mul(d,k),*t)}}
fn main(){counted::disable();let root="research/hec_residual_span_20261116";let raw=fs::read_to_string(format!("{root}/incidence-oracle/ROOTS.tsv")).unwrap();let mut triggers=BTreeMap::new();for l in fs::read_to_string(format!("{root}/affine-promotion/CONTROL.stderr")).unwrap().lines().filter(|l|l.starts_with("PROMOTE\t")){let v:Vec<_>=l.split('\t').collect();let n=|j:usize|v[j].parse::<u64>().unwrap();if n(7)!=0&&v[9]=="false"{triggers.entry((n(1),n(2))).or_insert((n(3),n(4),n(5)as usize,[n(6),n(7),n(8)]));}}
println!("p\tsm\ttrial\ti\tj\tsi\tsj\tsplit\trank\tnew_rank\tk");let(mut trials,mut accepted,mut bootstrap_solved)=(0,0,0);
for(p,cc,ell)in[(101,2,7481),(251,18,67931),(601,7,411491)]{let c=Curve::new(Fp::new(p),Poly::from_coeffs(&[cc,0,0,0,0,1]));let(fb,z,character)=fast::prepare(&c);let(_,_,degree,lambda)=algebra::certificate(&character,ell);assert_eq!(degree,1);let lambda=lambda.unwrap();let f=Fp::new(ell);let mut map=vec![(usize::MAX,0);fb.len()];let mut reps=vec![];for j in 0..fb.len(){if map[j].0!=usize::MAX{continue}let r=reps.len();reps.push(j);let(mut x,y,mut w)=(fb[j].0,fb[j].1,1);for _ in 0..5{let q=fb.binary_search_by_key(&x,|p|p.0).unwrap();map[q]=(r,if fb[q].1==y{w}else{assert_eq!(fb[q].1,c.fp.neg(y));f.neg(w)});x=c.fp.mul(x,z);w=f.mul(w,lambda);}}let cols=reps.len();let perm=|r:usize|if r==0{cols-1}else{r-1};let base=c.place(fb[0].0,fb[0].1);let mut rng=Rng::new(2026112500^p);
for sm in [1,17]{let d=c.mul(&base,sm);let q=1+rng.below(ell-1);let target=c.mul(&d,q);let Some(&(trigger_row,trigger_anchor,orbit,h))=triggers.get(&(p,sm))else{eprintln!("SUMMARY\t{p}\t{sm}\tno_trigger");continue};let mut affine=dsu::Affine::new(cols-1,ell);let mut generic=sparse::Sparse::new(cols+1,ell);let mut rows=vec![];if let Some((_,v))=source::equation(&c,&d,&fb,&map,cols,ell){let mut w=vec![0;cols+1];for(r,x)in v.into_iter().enumerate(){w[perm(r)]=x}insert(&c,&d,&target,ell,w,1,&mut rows,&mut affine,&mut generic)}let mut selected=0;for l in raw.lines().skip(1){let v:Vec<_>=l.split('\t').collect();if v[0].parse::<u64>().unwrap()!=p||v[1].parse::<u64>().unwrap()!=sm{continue}let support:Vec<Vec<u64>>=v[5].split(',').map(|s|s.split(':').map(|x|x.parse().unwrap()).collect()).collect();if !support.iter().any(|x|x[0]==0){continue}let mut coeff=vec![0;cols+1];for x in support{let j=fb.binary_search_by_key(&x[1],|p|p.0).unwrap();assert_eq!(map[j].0,x[0]as usize);let w=if x[2]==fb[j].1{map[j].1}else{assert_eq!(x[2],c.fp.neg(fb[j].1));f.neg(map[j].1)};let r=perm(map[j].0);coeff[r]=f.add(coeff[r],w)}coeff[cols]=1;let a=v[3].parse::<u64>().unwrap();insert(&c,&d,&target,ell,coeff,f.neg(a),&mut rows,&mut affine,&mut generic);selected+=1;if selected==trigger_row{break}}assert_eq!(selected,trigger_row);assert_eq!(affine.k(),None);assert_eq!(affine.expression(orbit-1),Some(h));let pj=reps[orbit];let promoted=(fb[pj].0,fb[pj].1);let point=c.place(promoted.0,promoted.1);let expected=c.add(&c.add(&c.mul(&base,h[0]),&c.mul(&target,h[1])),&c.mul(&d,h[2]));assert_eq!(point,expected);let mut core=vec![];let(mut x,mut w)=(fb[0].0,1);for _ in 0..5{core.push((x,fb[0].1,w));x=c.fp.mul(x,z);w=f.mul(w,lambda)}let mut promoted_orbit=vec![];let(mut xp,mut wp)=(promoted.0,1);for _ in 0..5{promoted_orbit.push((xp,promoted.1,wp));let actual=c.place(xp,promoted.1);let expected=c.add(&c.add(&c.mul(&base,f.mul(wp,h[0])),&c.mul(&target,f.mul(wp,h[1]))),&c.mul(&d,f.mul(wp,h[2])));assert_eq!(actual,expected);xp=c.fp.mul(xp,z);wp=f.mul(wp,lambda);}let start_rank=affine.rank();let(mut local_trial,mut local_split,mut first)=(0,0,None);
for i in 0..5{for j in i+1..5{for si in [1i64,-1]{for sj in [1i64,-1]{local_trial+=1;trials+=1;let yi=if si==1{promoted_orbit[i].1}else{c.fp.neg(promoted_orbit[i].1)};let yj=if sj==1{promoted_orbit[j].1}else{c.fp.neg(promoted_orbit[j].1)};let pts=[(core[0].0,core[0].1),(promoted_orbit[i].0,yi),(promoted_orbit[j].0,yj)];let sum=f.add(f.mul(f.from_i64(si),promoted_orbit[i].2),f.mul(f.from_i64(sj),promoted_orbit[j].2));let mut u=Poly::one();for &(x,_)in &pts{u=u.mul(&Poly::x_minus(x,&c.fp),&c.fp)}let mut v=Poly::zero();for a in 0..3{let mut basis=Poly::one();for b in 0..3{if a!=b{assert_ne!(pts[a].0,pts[b].0);basis=basis.mul(&Poly::x_minus(pts[b].0,&c.fp),&c.fp)}}let s=c.fp.mul(pts[a].1,c.fp.inv(basis.eval(pts[a].0,&c.fp)));v=v.add(&basis.scale(s,&c.fp),&c.fp)}let hpoly=c.f.sub(&v.mul(&v,&c.fp),&c.fp).div_exact(&u,&c.fp);assert_eq!(hpoly.deg(),2);let mut stats=OracleStats::default();let roots=split_reference(&hpoly,&c.fp,&mut stats);let before=affine.rank();if let Some(roots)=roots{let mut group=c.zero();for &(x,y)in &pts{group=c.add_place(&group,x,y)}let mut reconstructed=Poly::one();let mut coeff=vec![0;cols+1];coeff[cols-1]=f.add(1,f.mul(h[0],sum));coeff[cols]=f.mul(h[1],sum);for &(x,m)in roots.as_slice(){let y=v.eval(x,&c.fp);let idx=fb.binary_search_by_key(&x,|p|p.0).unwrap();let w=if y==fb[idx].1{map[idx].1}else{assert_eq!(y,c.fp.neg(fb[idx].1));f.neg(map[idx].1)};let r=perm(map[idx].0);coeff[r]=f.add(coeff[r],f.mul(w,m as u64));for _ in 0..m{group=c.add_place(&group,x,y);reconstructed=reconstructed.mul(&Poly::x_minus(x,&c.fp),&c.fp)}}assert_eq!(reconstructed,hpoly);assert!(c.is_zero(&group));insert(&c,&d,&target,ell,coeff,f.neg(f.mul(h[2],sum)),&mut rows,&mut affine,&mut generic);accepted+=1;local_split+=1;}if affine.k().is_some()&&first.is_none(){first=Some(local_trial);}println!("{p}\t{sm}\t{local_trial}\t{i}\t{j}\t{si}\t{sj}\t{}\t{}\t{}\t{}",roots.is_some(),affine.rank(),affine.rank()-before,affine.k().map_or("none".into(),|k|k.to_string()));}}}}
if first.is_some(){bootstrap_solved+=1}eprintln!("SUMMARY\t{p}\t{sm}\ttrigger_row={trigger_row}\ttrigger_anchor={trigger_anchor}\ttrials={local_trial}\tsplit={local_split}\tadded_rank={}\tfirst_k_trial={}\tfinal_k={}",affine.rank()-start_rank,first.map_or("none".into(),|x|x.to_string()),affine.k().map_or("none".into(),|x|x.to_string()));}}
assert_eq!(trials,200);eprintln!("trials={trials} accepted={accepted} bootstrap_solved={bootstrap_solved} all_polynomial_group_and_three_solver_checks=true original_no_trigger_retained=true");}
